mapper.select:
SELECT tenant_id,callback_id,delivery_id,fingerprint,authentication_ref,command_digest,registration_revision,verified_at
FROM public.agent_runtime_callback_ingress_proofs
WHERE tenant_id=#{ref.tenantId.value} AND delivery_id=#{ref.deliveryId}

mapper.update:
UPDATE public.agent_runtime_callback_deliveries SET status='DELIVERED',revision=#{row.revision},attempt=#{row.attempt},
    lease_claim=NULL,lease_worker=NULL,lease_token=NULL,lease_until=NULL,
    updated_at=#{row.updatedAt,typeHandler=com.skillforge.runtime.adapter.jdbc.callback.CallbackInstantTypeHandler}
WHERE tenant_id=#{row.tenantId} AND delivery_id=#{row.deliveryId} AND revision=#{before}
  AND status IN ('READY','PROCESSING') AND command_digest=#{row.commandDigest}

mapper.insert:
INSERT INTO agent_runtime_execution_workflow_callback_deliveries(tenant_id,delivery_id,run_id,action_id,generation,input_id)
SELECT w.tenant_id,#{ref.deliveryId},w.run_id,w.action_id,w.generation,#{envelope.inputId.value}
FROM agent_runtime_execution_waits w JOIN agent_runtime_execution_runs r ON r.tenant_id=w.tenant_id AND r.run_id=w.run_id
  AND r.waiting_action_id=w.action_id AND r.waiting_generation=w.generation
WHERE w.tenant_id=#{ref.tenantId.value} AND w.run_id=#{target.owningRunRef.runId} AND w.kind='WORKFLOW'
  AND w.execution_id=#{target.executionRef.executionId} AND w.action_key=#{target.actionKey} AND w.execution_revision=#{target.expectedExecutionRevision}
  AND w.input_id IS NULL AND r.phase='WAITING' AND NOT r.cancelled AND r.session_id=#{envelope.sessionRef.sessionId}
  AND r.target_kind=#{envelope.sessionTarget.kind} AND r.target_id=#{envelope.sessionTarget.id}
  AND r.agent_id=#{envelope.agentId.value} AND r.subject_kind='USER'
  AND r.subject_id=CAST(#{envelope.subject.endUserId.value} AS text)
  AND r.end_user_id=#{envelope.subject.endUserId.value}
ON CONFLICT DO NOTHING

mapper.select:
SELECT tenant_id, callback_id, idempotency_key, command_data, status, revision, created_at, updated_at FROM public.agent_runtime_callback_registrations
WHERE tenant_id = #{ref.tenantId.value} AND callback_id = #{ref.callbackId}
FOR UPDATE

mapper.update:
UPDATE public.agent_runtime_callback_registrations
SET status = #{row.status}, revision = #{row.revision}, updated_at = #{row.updatedAt}
WHERE tenant_id = #{row.tenantId} AND callback_id = #{row.callbackId} AND revision = #{before}

mapper.select:
SELECT tenant_id,delivery_id,callback_id,command_digest,input_id,envelope_data,status,revision,attempt,
       reason_code,audit_ref,lease_claim,lease_worker,lease_token,lease_until,available_at,recorded_at,updated_at
FROM public.agent_runtime_callback_deliveries WHERE  AND delivery_id>#{after}
  AND ((status='READY' AND available_at<=#{now}) OR (status='PROCESSING' AND lease_until<=#{now}))
ORDER BY delivery_id LIMIT #{limit}
